export const diaryThemes=[{id:'noche',name:'Zafiro luminoso',colors:['#e9efff','#d9f4f1']},{id:'petroleo',name:'Petroleo',colors:['#103735','#20544f']},{id:'uva',name:'Amatista',colors:['#291f3d','#473152']},{id:'grafito',name:'Grafito',colors:['#20252d','#3a4350']},{id:'claro',name:'Marfil',colors:['#e8e3d9','#f5f2ec']}];
export function accentText(hex){const c=hex.replace('#','');const rgb=[0,2,4].map(i=>parseInt(c.slice(i,i+2),16)/255).map(v=>v<=.04045?v/12.92:Math.pow((v+.055)/1.055,2.4));return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]>.179?'#102f36':'#ffffff'}
export function appearanceStyle(settings={}){const theme=diaryThemes.find(t=>t.id===settings.tema)||diaryThemes[0];const accent=/^#[a-f0-9]{6}$/i.test(settings.acento||'')?settings.acento:'#238d80';const result={'--diary-accent':accent,'--diary-accent-ink':accentText(accent),backgroundImage:'radial-gradient(ellipse at 0% 0%,#3c8b8b20,transparent 55%),linear-gradient(135deg,'+theme.colors[0]+','+theme.colors[1]+')'};const e=settings.entorno||{};if(e.activo&&['fondo','fondoFin','encabezado','panel'].every(k=>/^#[a-f0-9]{6}$/i.test(e[k]||''))){result.backgroundImage='linear-gradient(135deg,'+e.fondo+','+e.fondoFin+')';result['--diary-surface']=e.panel;result['--diary-surface-ink']=accentText(e.panel);result['--diary-header']=e.encabezado;result['--diary-header-ink']=accentText(e.encabezado);result['--diary-page-ink']=accentText(e.fondo);}if(settings.fondo)result.backgroundImage='linear-gradient(#0b1c32aa,#0b1c32b8),url('+JSON.stringify(settings.fondo)+')';return result;}



