const escape=value=>String(value==null?'':value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=value=>Number(value)||0;
const money=value=>'S/ '+number(value).toFixed(2);
export function projectPrintReport(data) {
  const project=data.project||{},company=data.company||{};
  const products=(data.products||[]).filter(item=>!item.isDisabled);
  const advances=(data.advances||[]).filter(item=>!Number(item.Anulado));
  const expenses=(data.expenses||[]).filter(item=>!Number(item.Anulado));
  const total=products.reduce((sum,item)=>sum+(Number(item.EsManoDeObra)===1?0:number(item.Precio)*number(item.Cantidad)),0);
  const advance=advances.reduce((sum,item)=>sum+Math.abs(number(item.Importe)),0),balance=Math.max(0,total-advance);
  const productRows=products.map(item=>`<tr><td>${escape(item.CodigoBarra||item.IdProducto)}</td><td class="product">${escape(item.Producto)}</td><td class="num">${escape(item.Cantidad)}</td><td class="num">${money(item.Precio)}</td><td class="num strong">${money(number(item.Precio)*number(item.Cantidad))}</td></tr>`).join('');
  const movementSection=(title,rows)=>rows.length?`<section><h2>${title}</h2><table><thead><tr><th>Fecha</th><th>Concepto</th><th class="num">Importe</th></tr></thead><tbody>${rows.map(item=>`<tr><td class="date">${escape(item.FechaDoc||item.FechaReg||'')}</td><td>${escape(item.Concepto)}</td><td class="num">${money(Math.abs(number(item.Importe)))}</td></tr>`).join('')}</tbody><tfoot><tr><td colspan="2">Total ${title.toLowerCase()}</td><td class="num">${money(rows.reduce((sum,item)=>sum+Math.abs(number(item.Importe)),0))}</td></tr></tfoot></table></section>`:'';
  return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reporte ${escape(project.Producto)}</title><style>
  @page{size:A4 portrait;margin:12mm}*{box-sizing:border-box}body{margin:0;background:#edf2f6;color:#233f50;font:11px Arial,sans-serif;line-height:1.45}.sheet{max-width:186mm;margin:22px auto;background:white;padding:24px;box-shadow:0 10px 40px #112c4514}.toolbar{max-width:186mm;margin:18px auto;text-align:right}.toolbar button{border:0;background:#153b50;color:white;border-radius:8px;padding:11px 20px;cursor:pointer}header{display:flex;align-items:center;justify-content:space-between;gap:20px;border-bottom:3px solid #168e94;padding-bottom:17px;margin-bottom:18px}.brand{display:flex;gap:15px;align-items:center}.brand img{width:42mm;max-height:18mm;object-fit:contain}.company{font-size:10px;max-width:55mm;color:#607885}.report-label{text-align:right}.eyebrow{font-size:8px;letter-spacing:1.6px;font-weight:bold;color:#168e94}h1{font-size:22px;line-height:1.15;margin:5px 0;color:#17394d}.muted{color:#718590;font-size:9px}.info{display:grid;grid-template-columns:1.4fr 1fr;gap:8px 25px;padding:14px 17px;background:#f4f8fa;border:1px solid #e1ebef;border-radius:8px;margin-bottom:15px}.info div{min-width:0;overflow-wrap:anywhere}.label{display:block;font-size:8px;text-transform:uppercase;letter-spacing:.5px;color:#7a8e99;margin-bottom:3px}.description{border-left:3px solid #168e94;padding:2px 12px;margin:14px 0 18px;white-space:pre-wrap;overflow-wrap:anywhere}section{margin-top:18px}h2{font-size:11px;color:#17394d;margin:0 0 8px;font-weight:bold}table{width:100%;border-collapse:collapse;table-layout:auto;font-size:10px}thead{display:table-header-group}th{background:#eaf1f5;color:#294b5e;text-align:left;padding:8px;border-bottom:1px solid #cbdce6;font-size:9px}td{padding:8px;border-bottom:1px solid #e8eef2;vertical-align:top;overflow-wrap:anywhere}tr{break-inside:avoid}.product{width:49%;font-weight:600}.num{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}.strong,tfoot{font-weight:bold}.date{width:27%;font-size:9px}tfoot td{background:#f5f9fb}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:20px 0;padding-top:14px;border-top:1px solid #dbe6ec;break-inside:avoid}.summary>div{background:#f2f6f9;border:1px solid #e2ebef;border-radius:8px;padding:13px}.summary b{font-size:19px;color:#21485b;display:block;margin-top:5px}.summary .due{background:#163c50;border-color:#163c50}.summary .due .label{color:#c2dce5}.summary .due b{color:white}.operations{font-size:9px;color:#718590;padding:8px 0;border-bottom:1px solid #e5edf1}footer{margin-top:23px;padding-top:9px;border-top:1px solid #dbe6ec;display:flex;justify-content:space-between;gap:12px;font-size:8px;color:#8a9ba5}
  @media print{body{background:#fff}.sheet{max-width:none;margin:0;padding:0;box-shadow:none}.toolbar{display:none}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}
  @media screen and (max-width:600px){.sheet{padding:15px;margin:10px}header{flex-wrap:wrap}.brand img{width:33mm}.info{grid-template-columns:1fr}.summary{gap:6px}.summary>div{padding:9px}.summary b{font-size:15px}}
  </style></head><body><div class="toolbar"><button onclick="window.print()">Imprimir / Guardar PDF</button></div><main class="sheet"><header><div class="brand"><img src="/resources/images/logo-ticket.png" alt="Logo"><div class="company"><b>${escape(company.RAZONSOCIAL||'NEUROSYSTEM')}</b><br>${company.RUC?'RUC: '+escape(company.RUC):''}</div></div><div class="report-label"><span class="eyebrow">REPORTE DE SERVICIO</span><h1>${escape(project.Producto||'Proyecto')}</h1><span class="muted">Código ${escape(project.IdProducto)} · ${escape(data.date)}</span></div></header>
  <div class="info"><div><span class="label">Cliente</span><b>${escape(project.Cliente)}</b></div><div><span class="label">Documento</span>${escape(project.DniRuc)}</div><div><span class="label">Teléfono</span>${escape(project.Telefono||'Sin teléfono registrado')}</div><div><span class="label">Periodo del servicio</span>${escape(project.FechaAlquiler||'Sin fecha')} → ${escape(project.FechaAlquilerFin||'Sin fecha')}</div><div><span class="label">Personal de servicio</span>${escape(project.Empleado||'Sin personal asignado')}</div><div><span class="label">Generado por</span>${escape(data.user||'')}</div></div>
  ${project.Descripcion?'<div class="description"><span class="label">Descripción del proyecto</span>'+escape(project.Descripcion)+'</div>':''}
  <section><h2>Productos y servicios</h2><table><thead><tr><th>Código</th><th>Descripción</th><th class="num">Cant.</th><th class="num">P. unitario</th><th class="num">Importe</th></tr></thead><tbody>${productRows||'<tr><td colspan="5">Sin productos registrados.</td></tr>'}</tbody></table></section>
  ${movementSection('Adelantos',advances)}${movementSection('Gastos',expenses)}
  <div class="summary"><div><span class="label">Total del proyecto</span><b>${money(total)}</b></div><div><span class="label">Adelanto recibido</span><b>${money(advance)}</b></div><div class="due"><span class="label">Saldo pendiente</span><b>${money(balance)}</b></div></div>
  <div class="operations">Mano de obra bruta: ${money(data.labor)} &nbsp; · &nbsp; Mano de obra neta: ${money(data.netLabor)} &nbsp; · &nbsp; Gastos: ${money(expenses.reduce((sum,item)=>sum+Math.abs(number(item.Importe)),0))}</div>
  <footer><span>Detalle del proyecto · Documento informativo</span><span>${escape(project.Producto)} / ${escape(project.IdProducto)}</span></footer></main></body></html>`;
}



