.diary-report-nav{display:flex;align-items:center;gap:12px;padding:10px 14px;border:1px solid #dce7ef;border-radius:10px;background:#f7fafc;margin-bottom:12px}.diary-report-nav small{font-size:9px;letter-spacing:1px;color:#7890a1}.diary-report-nav button{font-size:11px;color:#34667c;background:#edf4f8;border-color:#d6e5ee}.diary-report-nav button.selected{background:#234d65;color:white}@media(max-width:800px){.diary-report-nav{align-items:flex-start;flex-direction:column;gap:8px}}
.diary-task-technical{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0}.diary-task-technical span{background:#edf4f8;border:1px solid #dce8f0;color:#50758c;border-radius:6px;padding:4px 7px;font-size:10px}
.diary-compact-bar{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:12px 16px;background:#fff;border:1px solid #dce6ee;border-radius:12px}.diary-compact-bar>div{display:flex;gap:10px;align-items:center}.diary-compact-bar h1{margin:0;font-size:16px;color:#294b62}.diary-compact-bar small{color:#8ba0ae;font-size:10px}.diary-query-tools{margin:10px 0;border:1px solid #e0e8ef;border-radius:10px;background:#fff;padding:10px 14px}.diary-query-tools>summary{font-size:11px;color:#6b879a;cursor:pointer}.diary-page{max-width:none;padding:12px 16px 50px}.diary-workspaces{margin:10px 0 0;padding-bottom:8px}.diary-tabs{margin:10px 0}.diary-board-shell{padding:14px}.diary-board-toolbar small,.diary-board-shell>.diary-hint{display:none}@media(max-width:650px){.diary-compact-bar{align-items:flex-start;flex-direction:column}.diary-compact-bar small{display:none}.diary-compact-bar button{font-size:11px}.diary-page{padding:8px 8px 50px}}
</style>

